    /// <description>Integer. Optional. Limits the number of updates to be retrieved. Values between 1-100 are accepted. Defaults to 100.</description>
    /// </item>
    /// <item>
    /// <term>timeout</term>
    /// <description>Integer. Optional. Timeout in seconds for long polling. Defaults to 0, i.e. usual short polling. Should be positive, short polling should be used for testing purposes only.</description>
    /// </item>
    /// <item>
    /// <term>allowed_updates</term>
    /// <description>Array of String. Optional. A JSON-serialized list of the update types you want your bot to receive. For example, specify [&quot;message&quot;, &quot;edited_channel_post&quot;, &quot;callback_query&quot;] to only receive updates of these types. See Update for a complete list of available update types. Specify an empty list to receive all update types except chat_member, message_reaction, and message_reaction_count (default). If not specified, the previous setting will be used. Please note that this parameter doesn&apos;t affect updates created before the call to getUpdates, so unwanted updates may be received for a short period of time.</description>
    /// </item>
    /// </list>
    /// </remarks>
    public Task<IReadOnlyList<PPSHGram.Telegram.Generated.Types.Update>> GetUpdates(
