    /// <summary>
    /// Use this method to send invoices. On success, the sent Message is returned.
    /// </summary>
    /// <remarks>
    /// <para>Parameters:</para>
    /// <list type="bullet">
    /// <item>
    /// <term>chat_id</term>
    /// <description>Integer or String. Required. Unique identifier for the target chat or username of the target bot, supergroup or channel in the format @username</description>
    /// </item>
    /// <item>
    /// <term>message_thread_id</term>
    /// <description>Integer. Optional. Unique identifier for the target message thread (topic) of a forum; for forum supergroups and private chats of bots with forum topic mode enabled only</description>
    /// </item>
    /// <item>
    /// <term>direct_messages_topic_id</term>
    /// <description>Integer. Optional. Identifier of the direct messages topic to which the message will be sent; required if the message is sent to a direct messages chat</description>
    /// </item>
    /// <item>
    /// <term>title</term>
    /// <description>String. Required. Product name, 1-32 characters</description>
    /// </item>
    /// <item>
    /// <term>description</term>
    /// <description>String. Required. Product description, 1-255 characters</description>
    /// </item>
    /// <item>
    /// <term>payload</term>
    /// <description>String. Required. Bot-defined invoice payload, 1-128 bytes. This will not be displayed to the user, use it for your internal processes.</description>
    /// </item>
    /// <item>
    /// <term>provider_token</term>
    /// <description>String. Optional. Payment provider token, obtained via @BotFather. Pass an empty string for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>currency</term>
    /// <description>String. Required. Three-letter ISO 4217 currency code, see more on currencies. Pass “XTR” for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>prices</term>
    /// <description>Array of LabeledPrice. Required. Price breakdown, a JSON-serialized list of components (e.g. product price, tax, discount, delivery cost, delivery tax, bonus, etc.). Must contain exactly one item for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>max_tip_amount</term>
    /// <description>Integer. Optional. The maximum accepted amount for tips in the smallest units of the currency (integer, not float/double). For example, for a maximum tip of US$ 1.45 pass max_tip_amount = 145. See the exp parameter in currencies.json, it shows the number of digits past the decimal point for each currency (2 for the majority of currencies). Defaults to 0. Not supported for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>suggested_tip_amounts</term>
    /// <description>Array of Integer. Optional. A JSON-serialized array of suggested amounts of tips in the smallest units of the currency (integer, not float/double). At most 4 suggested tip amounts can be specified. The suggested tip amounts must be positive, passed in a strictly increased order and must not exceed max_tip_amount.</description>
    /// </item>
    /// <item>
    /// <term>start_parameter</term>
    /// <description>String. Optional. Unique deep-linking parameter. If left empty, forwarded copies of the sent message will have a Pay button, allowing multiple users to pay directly from the forwarded message, using the same invoice. If non-empty, forwarded copies of the sent message will have a URL button with a deep link to the bot (instead of a Pay button), with the value used as the start parameter.</description>
    /// </item>
    /// <item>
    /// <term>provider_data</term>
    /// <description>String. Optional. JSON-serialized data about the invoice, which will be shared with the payment provider. A detailed description of required fields should be provided by the payment provider.</description>
    /// </item>
    /// <item>
    /// <term>photo_url</term>
    /// <description>String. Optional. URL of the product photo for the invoice. Can be a photo of the goods or a marketing image for a service. People like it better when they see what they are paying for.</description>
    /// </item>
    /// <item>
    /// <term>photo_size</term>
    /// <description>Integer. Optional. Photo size in bytes</description>
    /// </item>
    /// <item>
    /// <term>photo_width</term>
    /// <description>Integer. Optional. Photo width</description>
    /// </item>
    /// <item>
    /// <term>photo_height</term>
    /// <description>Integer. Optional. Photo height</description>
    /// </item>
    /// <item>
    /// <term>need_name</term>
    /// <description>Boolean. Optional. Pass True if you require the user&apos;s full name to complete the order. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>need_phone_number</term>
    /// <description>Boolean. Optional. Pass True if you require the user&apos;s phone number to complete the order. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>need_email</term>
    /// <description>Boolean. Optional. Pass True if you require the user&apos;s email address to complete the order. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>need_shipping_address</term>
    /// <description>Boolean. Optional. Pass True if you require the user&apos;s shipping address to complete the order. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>send_phone_number_to_provider</term>
    /// <description>Boolean. Optional. Pass True if the user&apos;s phone number should be sent to the provider. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>send_email_to_provider</term>
    /// <description>Boolean. Optional. Pass True if the user&apos;s email address should be sent to the provider. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>is_flexible</term>
    /// <description>Boolean. Optional. Pass True if the final price depends on the shipping method. Ignored for payments in Telegram Stars.</description>
    /// </item>
    /// <item>
    /// <term>disable_notification</term>
    /// <description>Boolean. Optional. Sends the message silently. Users will receive a notification with no sound.</description>
    /// </item>
    /// <item>
    /// <term>protect_content</term>
    /// <description>Boolean. Optional. Protects the contents of the sent message from forwarding and saving</description>
    /// </item>
    /// <item>
    /// <term>allow_paid_broadcast</term>
    /// <description>Boolean. Optional. Pass True to allow up to 1000 messages per second, ignoring broadcasting limits for a fee of 0.1 Telegram Stars per message. The relevant Stars will be withdrawn from the bot&apos;s balance.</description>
    /// </item>
    /// <item>
    /// <term>message_effect_id</term>
