    /// <description>Boolean. Optional. Pass True, if the poll allows multiple answers, defaults to False</description>
    /// </item>
    /// <item>
    /// <term>allows_revoting</term>
    /// <description>Boolean. Optional. Pass True, if the poll allows to change chosen answer options, defaults to False for quizzes and to True for regular polls</description>
    /// </item>
    /// <item>
    /// <term>shuffle_options</term>
    /// <description>Boolean. Optional. Pass True, if the poll options must be shown in random order</description>
    /// </item>
    /// <item>
    /// <term>allow_adding_options</term>
    /// <description>Boolean. Optional. Pass True, if answer options can be added to the poll after creation; not supported for anonymous polls and quizzes</description>
    /// </item>
    /// <item>
    /// <term>hide_results_until_closes</term>
    /// <description>Boolean. Optional. Pass True, if poll results must be shown only after the poll closes</description>
    /// </item>
    /// <item>
    /// <term>members_only</term>
    /// <description>Boolean. Optional. Pass True, if voting is limited to users who have been members of the chat where the poll is being sent for more than 24 hours; for channel chats only</description>
