    /// <description>Integer. Required. Unique identifier of the target user</description>
    /// </item>
    /// <item>
    /// <term>only_if_banned</term>
    /// <description>Boolean. Optional. Do nothing if the user is not banned</description>
    /// </item>
    /// </list>
    /// </remarks>
    public Task<bool> UnbanChatMember(
        UnbanChatMemberRequest request,
        CancellationToken cancellationToken = default)
    {
        return CallAsync<bool>(TelegramMethods.UnbanChatMember, request, cancellationToken);
    }

